function renderDiffComparison(leftLabel,rightLabel,leftText,rightText){const operations=lineDiff(leftText,rightText),added=operations.filter(item=>item.type==='add').length,removed=operations.filter(item=>item.type==='remove').length,changed=added+removed;q('diffTitle').textContent='文件对比 · '+leftLabel+' ↔ '+rightLabel;q('diffBefore').textContent=numberedText(leftText);q('diffAfter').textContent=numberedText(rightText);q('diffSummary').textContent=changed?'新增 '+added+' 行 · 删除 '+removed+' 行':'内容一致';q('diffDetails').replaceChildren();const details=operations.filter(item=>item.type!=='same');if(!details.length){const empty=document.createElement('div');empty.className='diff-empty';empty.textContent='两个版本没有文本差异';q('diffDetails').append(empty);return}for(const operation of details.slice(0,2000))appendDiffLine(operation);if(details.length>2000){const empty=document.createElement('div');empty.className='diff-empty';empty.textContent='差异较多，仅显示前 2000 行';q('diffDetails').append(empty)}}
async function compareSelectedFiles(){const left=q('diffLeftFile').value,right=q('diffRightFile').value;if(!right)throw new Error('请选择右侧文件');if(left==='__baseline__'){const data=await api(endpoint('diff',right)).then(response=>response.json());renderDiffComparison(right+' · 模板基线',right,data.original,data.current);return}if(!left)throw new Error('请选择左侧文件');const [leftText,rightText]=await Promise.all([api(endpoint('file',left)).then(response=>response.text()),api(endpoint('file',right)).then(response=>response.text())]);renderDiffComparison(left,right,leftText,rightText)}
async function showDiff(){const paths=textFilePaths(),left=q('diffLeftFile'),right=q('diffRightFile');left.replaceChildren(diffOption('__baseline__','当前文件 · 模板基线'),...paths.map(path=>diffOption(path)));right.replaceChildren(...paths.map(path=>diffOption(path)));if(paths.includes(currentPath))right.value=currentPath;q('diffModal').style.display='grid';await compareSelectedFiles()}
async function jumpToDiagnostic(diagnostic){if(!diagnostic.path||!treeFiles.has(diagnostic.path))return;q('validationModal').style.display='none';await loadFile(diagnostic.path);document.body.className='mobile-editor';document.querySelectorAll('[data-view]').forEach(item=>item.classList.toggle('active',item.dataset.view==='editor'));if(currentKind==='text'&&diagnostic.line){editor.setCursor({line:Math.max(0,diagnostic.line-1),ch:Math.max(0,(diagnostic.column||1)-1)});editor.focus();editor.scrollIntoView({line:Math.max(0,diagnostic.line-1),ch:0},80)}}
function renderValidation(data){lastValidationData=data;const summary=q('validationSummary'),list=q('validationList');summary.textContent=data.valid?'校验通过 · '+data.fileCount+' 个文件':data.errorCount+' 个错误 · '+data.warningCount+' 个警告';summary.className='validation-summary '+(data.valid?'valid':'invalid');list.replaceChildren();if(!data.diagnostics.length){const empty=document.createElement('div');empty.className='validation-empty';empty.textContent='项目结构和资源引用校验通过';list.append(empty);return}const labels={error:'错误',warning:'警告',info:'信息'};for(const diagnostic of data.diagnostics){const item=document.createElement('button'),level=document.createElement('span'),title=document.createElement('span'),location=document.createElement('span'),hint=document.createElement('span'),exists=treeFiles.has(diagnostic.path);item.className='validation-item'+(exists?'':' no-path');level.className='validation-level '+diagnostic.severity;level.textContent=labels[diagnostic.severity]||diagnostic.severity;title.className='validation-message';title.textContent=diagnostic.message;location.className='validation-location';location.textContent=diagnostic.path+(diagnostic.line?' · '+diagnostic.line+':'+(diagnostic.column||1):'')+' · '+diagnostic.code;hint.className='validation-hint';hint.textContent=diagnostic.hint||'';item.append(level,title,location,hint);if(exists)item.onclick=()=>jumpToDiagnostic(diagnostic).catch(e=>message.textContent=e.message);list.append(item)}}
function validationText(data){const labels={error:'错误',warning:'警告',info:'信息'},lines=['项目校验：'+(data.valid?'通过':'未通过'),'文件：'+data.fileCount+' · 错误：'+data.errorCount+' · 警告：'+data.warningCount];if(!data.diagnostics.length)lines.push('没有校验问题。');for(const diagnostic of data.diagnostics){const location=diagnostic.path+(diagnostic.line?':'+diagnostic.line+':'+(diagnostic.column||1):'');lines.push('', '['+(labels[diagnostic.severity]||diagnostic.severity)+'] '+diagnostic.code,location,diagnostic.message);if(diagnostic.hint)lines.push('修复建议：'+diagnostic.hint)}return lines.join(nl)}
async function copyValidation(){if(!lastValidationData){message.textContent='请先校验项目';return}await copyText(validationText(lastValidationData));message.textContent='已复制校验详情'}
async function validateProject(show=true){const data=await api(endpoint('validate','')).then(r=>r.json());renderValidation(data);if(show||!data.valid)q('validationModal').style.display='grid';message.textContent=data.valid?'项目校验通过':'项目校验发现 '+data.errorCount+' 个错误';return data}
