async function pollRun(){const requestId=++runPollRequest;if(runPollTimer){clearTimeout(runPollTimer);runPollTimer=null}if(!projectId)return;const requestedProjectId=projectId,data=await api(endpoint('run','')).then(r=>r.json());if(requestId!==runPollRequest||requestedProjectId!==projectId)return;renderRunStatus(data);if(data.phase==='starting'||data.phase==='running')runPollTimer=setTimeout(()=>pollRun().catch(e=>message.textContent=e.message),1200)}
