function generateProjectId(){const alphabet='abcdefghijklmnopqrstuvwxyz0123456789',size=10,browserCrypto=window.crypto,values=new Uint8Array(size);if(browserCrypto&&typeof browserCrypto.getRandomValues==='function')browserCrypto.getRandomValues(values);else for(let index=0;index<size;index++)values[index]=Math.floor(Math.random()*256);const suffix=Array.from(values,value=>alphabet[value%alphabet.length]).join('');q('projectId').value='com.playmesh.game-'+suffix;q('projectId').focus()}
