function renderCapabilityOptions(required=[],hostId='capabilityOptions'){const selected=new Set(required),host=q(hostId);host.replaceChildren(...capabilityDefinitions.map(definition=>{const label=document.createElement('label'),checkbox=document.createElement('input'),body=document.createElement('span'),name=document.createElement('strong'),description=document.createElement('p'),code=document.createElement('code'),contract=document.createElement('small'),badges=document.createElement('span');label.className='capability-option';checkbox.type='checkbox';checkbox.dataset.capabilityCode=definition.code;checkbox.checked=selected.has(definition.code);name.textContent=definition.name;description.textContent=definition.description;code.textContent=definition.code;contract.textContent=capabilityContract(definition);body.append(name,description,code,contract);badges.className='capability-badges';badges.append(supportBadge('App',definition.appSupported),supportBadge('HTML',definition.htmlSupported));label.append(checkbox,body,badges);return label}))}
