async function openManifestSettings(){if(!projectId)return;const [manifestData,capabilityData,registryData]=await Promise.all([api(endpoint('manifest','')).then(r=>r.json()),api(endpoint('capabilities','')).then(r=>r.json()),api('/dev/api/capabilities').then(r=>r.json())]);manifestRevision=manifestData.revision;capabilityRevision=capabilityData.revision;manifestSource=manifestData.manifest;capabilityDefinitions=registryData.capabilities||[];const manifest=manifestSource;q('manifestId').value=manifest.id||'';q('manifestName').value=manifest.name||'';q('manifestRemarks').value=manifest.remarks||'';q('manifestVersion').value=manifest.version||'';q('manifestSdkVersion').value=manifest.sdkVersion||'';q('manifestOrientation').value=manifest.orientation||'landscape';q('manifestMode').value=manifest.modes?.[0]||'multiplayer';q('manifestDisplayMode').value=manifest.displayModes?.[0]||'multi_screen';q('manifestMin').value=manifest.players?.min??1;q('manifestMax').value=manifest.players?.max??1;q('manifestIcon').value=manifest.icon||'';q('manifestGameEntry').value=manifest.entries?.game||'app/index.html';q('manifestControllerEntry').value=manifest.entries?.controller||'app/controller/index.html';q('manifestAuthorityEntry').value=manifest.authority?.entry||'';q('manifestPermissions').value=(manifest.permissions||[]).join('\n');manifestTags=[...(manifest.tags||[])];q('manifestTagInput').value='';q('manifestError').textContent='';q('manifestState').textContent='';renderManifestTags();renderCapabilityOptions(capabilityData.required);syncManifestMode();q('manifestModal').style.display='grid'}
function manifestFromForm(){const mode=q('manifestMode').value,manifest={...manifestSource,id:manifestSource.id,name:q('manifestName').value.trim(),remarks:q('manifestRemarks').value.trim(),version:q('manifestVersion').value.trim(),sdkVersion:q('manifestSdkVersion').value.trim(),orientation:q('manifestOrientation').value,modes:[mode],displayModes:[q('manifestDisplayMode').value],players:{min:Number(q('manifestMin').value),max:Number(q('manifestMax').value)},entries:{game:q('manifestGameEntry').value.trim(),controller:q('manifestControllerEntry').value.trim()},permissions:listInput(q('manifestPermissions').value),tags:[...manifestTags]};const icon=q('manifestIcon').value.trim(),authority=q('manifestAuthorityEntry').value.trim();if(icon)manifest.icon=icon;else delete manifest.icon;if(mode==='multiplayer')manifest.authority={entry:authority};else delete manifest.authority;return manifest}
async function saveManifestSettings(event){event.preventDefault();q('manifestError').textContent='';q('manifestState').textContent='正在保存';try{const manifest=manifestFromForm(),required=Array.from(q('capabilityOptions').querySelectorAll('input[data-capability-code]:checked'),input=>input.dataset.capabilityCode);const manifestData=await api(endpoint('manifest',''),{method:'PUT',body:JSON.stringify({manifest,baseRevision:manifestRevision,clientId})}).then(r=>r.json());manifestRevision=manifestData.revision;manifestSource=manifestData.manifest;const capabilityData=await api(endpoint('capabilities',''),{method:'PUT',body:JSON.stringify({required,baseRevision:capabilityRevision,clientId})}).then(r=>r.json());capabilityRevision=capabilityData.revision;q('manifestState').textContent='已保存';q('manifestModal').style.display='none';const selected=projectId;await loadProjects(selected);if(currentPath==='main.json'||currentPath==='capabilities.json')await loadFile(currentPath);message.textContent='已保存项目设置'}catch(error){q('manifestState').textContent='';q('manifestError').textContent=error.message}}
function applyEvent(event){if(event.projectId!==projectId)return;if(event.type==='project.validated'){message.textContent=event.valid?'项目校验通过':'项目校验发现 '+event.errorCount+' 个错误';return}if(event.type==='workspace.restored'){currentPath='';editor.setValue('');showEditor();loadTree();message.textContent=(event.clientId||'remote')+' · 已恢复本地历史 '+(event.path||'整个工作区');return}if(event.type==='directory.created'){loadTreeOnly();message.textContent=(event.clientId||'remote')+' · 已创建文件夹 '+event.path;return}if(event.type==='directory.deleted'){if(currentPath===event.path||currentPath.startsWith(event.path+'/')){currentPath='';editor.setValue('');showEditor()}loadTree();message.textContent=(event.clientId||'remote')+' · 已删除文件夹 '+event.path;return}if(event.type==='file.deleted'){if(event.path===currentPath){currentPath='';editor.setValue('');showEditor()}loadTree();return}if(event.path===currentPath&&currentKind!=='text'){loadAsset(event.path);return}if(event.path===currentPath){if(event.clientId!==clientId){for(const op of event.operations||[]){editor.replaceRange(op.text,editor.posFromIndex(op.start),editor.posFromIndex(op.end),'remote')}cleanValue=editor.getValue();q('dirty').textContent=''}revision=event.revision;q('revision').textContent='rev '+revision;message.textContent=event.clientId+' · '+event.type+' · '+event.path}loadTreeOnly()}
const logLines=[];function appendLog(event){const time=new Date(event.timestamp).toLocaleTimeString(),kind=event.eventType&&event.eventType!=='console'?' ['+event.eventType+']':'',location=event.filename?' ('+event.filename+(event.line?':'+event.line+(event.column?':'+event.column:''):'')+')':'',stack=event.stack&&!String(event.message).includes(event.stack)?nl+event.stack:'',line='['+time+'] ['+event.source+'] ['+event.level+']'+kind+' '+event.message+location+stack;logLines.push(line);if(logLines.length>500)logLines.splice(0,logLines.length-500);q('logs').textContent=logLines.join(nl);q('logs').scrollTop=q('logs').scrollHeight}
async function copyText(value){if(navigator.clipboard&&typeof navigator.clipboard.writeText==='function'){try{await navigator.clipboard.writeText(value);return}catch(_){}}const input=document.createElement('textarea');input.value=value;input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();const copied=document.execCommand('copy');input.remove();if(!copied)throw new Error('浏览器拒绝复制，请长按文本后复制')}
async function copyCurrentFile(){if(!currentPath||currentKind!=='text')throw new Error('当前没有可复制的文本文件');const content=editor.getValue();await copyText(content);message.textContent='已复制 '+currentPath+' · '+content.length+' 个字符'}
async function copyLogs(){if(!logLines.length){message.textContent='暂无日志可复制';return}await copyText(logLines.join(nl));message.textContent='已复制最近 '+logLines.length+' 条日志'}
let capabilityTestItems=[],capabilityTestResults=new Map(),capabilityTestGeneration=0,capabilityTestLogLines=[];
function renderCapabilityTests(items){const host=q('capabilityTestList');host.replaceChildren(...items.map(item=>{const row=document.createElement('div'),body=document.createElement('div'),name=document.createElement('strong'),code=document.createElement('code'),contract=document.createElement('small'),state=document.createElement('span'),button=document.createElement('button'),result=capabilityTestResults.get(item.code);row.className='capability-test-item';name.textContent=item.name;code.textContent=item.code;contract.textContent=capabilityContract(item);state.className=result?.status||'';state.textContent=result?result.status+' · '+result.message:(item.platformAvailable?'可测试':'当前平台不可用');button.textContent='持续测试';button.disabled=!item.testable;button.onclick=()=>runCapabilityTests([item.code]).catch(e=>state.textContent=e.message);body.append(name,code,contract,state);row.append(body,button);return row}))}
function appendCapabilityTestResults(results){const stamp=new Date().toLocaleTimeString();for(const result of results){capabilityTestResults.set(result.code,result);const detail={...result};delete detail.code;delete detail.name;capabilityTestLogLines.push('['+stamp+'] '+result.name+' ('+result.code+')'+nl+JSON.stringify(detail,null,2))}if(capabilityTestLogLines.length>500)capabilityTestLogLines.splice(0,capabilityTestLogLines.length-500);const log=q('capabilityTestLog');log.textContent=capabilityTestLogLines.join(nl+nl);log.scrollTop=log.scrollHeight;renderCapabilityTests(capabilityTestItems)}
function stopCapabilityTests(){capabilityTestGeneration++;q('runAllCapabilityTests').disabled=false;if(q('capabilityTestSummary').textContent.includes('持续测试'))q('capabilityTestSummary').textContent='测试已停止'}
async function openCapabilityTests(){stopCapabilityTests();capabilityTestResults=new Map();capabilityTestLogLines=[];q('capabilityTestLog').textContent='选择一项能力或测试全部后开始回显数据';q('capabilityTestSummary').textContent='正在读取能力注册表';q('capabilityTestModal').style.display='grid';const data=await api('/dev/api/capability-tests').then(r=>r.json());capabilityTestItems=data.capabilities||[];renderCapabilityTests(capabilityTestItems);q('capabilityTestSummary').textContent=capabilityTestItems.length+' 项能力'}
async function runCapabilityTests(codes){const generation=++capabilityTestGeneration,selectedCodes=Array.isArray(codes)&&codes.length?codes:null;q('runAllCapabilityTests').disabled=true;q('capabilityTestSummary').textContent='持续测试中…关闭窗口停止';capabilityTestLogLines=[];q('capabilityTestLog').textContent='等待能力返回数据…';while(generation===capabilityTestGeneration&&q('capabilityTestModal').style.display==='grid'){try{const data=await api('/dev/api/capability-tests',{method:'POST',body:JSON.stringify({codes:selectedCodes,timeoutMs:3000})}).then(r=>r.json());if(generation!==capabilityTestGeneration)break;appendCapabilityTestResults(data.results||[]);q('capabilityTestSummary').textContent=data.passed+' / '+data.total+' 通过 · 持续测试中'}catch(error){if(generation!==capabilityTestGeneration)break;capabilityTestLogLines.push('['+new Date().toLocaleTimeString()+'] 请求失败'+nl+error.message);q('capabilityTestLog').textContent=capabilityTestLogLines.join(nl+nl);q('capabilityTestSummary').textContent='请求失败，正在重试'}await new Promise(resolve=>setTimeout(resolve,350))}if(generation===capabilityTestGeneration)stopCapabilityTests()}
